// FALLING SQUARES (#699) — lazy segment tree + coordinate compression
function fallingSquares(positions) {
    // STEP 1: Coordinate compression
    const coords = new Set();
    for (const [l, size] of positions) {
        coords.add(l);
        coords.add(l + size - 1);
    }
    const sorted = [...coords].sort((a,b) => a-b);
    const compress = new Map(sorted.map((v,i) => [v, i+1])); // 1-indexed
    const n = sorted.length;

    // STEP 2: Lazy segment tree for range max (heights)
    const tree = new Array(4*(n+1)).fill(0);
    const lazy = new Array(4*(n+1)).fill(0);

    function pushDown(node) {
        if (lazy[node] > 0) {
            tree[2*node]   = Math.max(tree[2*node],   lazy[node]);
            lazy[2*node]   = Math.max(lazy[2*node],   lazy[node]);
            tree[2*node+1] = Math.max(tree[2*node+1], lazy[node]);
            lazy[2*node+1] = Math.max(lazy[2*node+1], lazy[node]);
            lazy[node] = 0;
        }
    }

    function update(ql, qr, val, node=1, l=1, r=n) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            tree[node] = Math.max(tree[node], val);
            lazy[node] = Math.max(lazy[node], val);
            return;
        }
        pushDown(node);
        const mid = (l+r)>>1;
        update(ql, qr, val, 2*node, l, mid);
        update(ql, qr, val, 2*node+1, mid+1, r);
        tree[node] = Math.max(tree[2*node], tree[2*node+1]);
    }

    function query(ql, qr, node=1, l=1, r=n) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return tree[node];
        pushDown(node);
        const mid = (l+r)>>1;
        return Math.max(query(ql, qr, 2*node, l, mid), query(ql, qr, 2*node+1, mid+1, r));
    }

    // STEP 3: Process each falling square
    const result = [];
    let maxHeight = 0;
    for (const [l, size] of positions) {
        const cl = compress.get(l);
        const cr = compress.get(l + size - 1);
        const base = query(cl, cr); // current max height in range
        const newHeight = base + size;
        update(cl, cr, newHeight); // set new height for this range
        maxHeight = Math.max(maxHeight, newHeight);
        result.push(maxHeight);
    }
    return result;
}

