// For a weighted tree: query max edge weight on any path u-v

class HLD {
    constructor(n, adj, vals) {
        this.n = n;
        this.adj = adj;   // adjacency list
        this.vals = vals; // node values
        this.parent = new Array(n).fill(-1);
        this.depth  = new Array(n).fill(0);
        this.size   = new Array(n).fill(1);
        this.heavy  = new Array(n).fill(-1); // heavy child
        this.head   = new Array(n).fill(0);  // chain head
        this.pos    = new Array(n).fill(0);  // DFS position (for seg tree)
        this.cur    = 0;

        // DFS 1: compute subtree sizes and heavy children
        this._dfs1(0, -1, 0);
        // DFS 2: assign DFS positions (chain-contiguous)
        this._dfs2(0, 0);
    }

    _dfs1(v, p, d) {
        this.parent[v] = p;
        this.depth[v]  = d;
        let maxSize = 0;
        for (const u of this.adj[v]) {
            if (u === p) continue;
            this._dfs1(u, v, d+1);
            this.size[v] += this.size[u];
            if (this.size[u] > maxSize) {
                maxSize = this.size[u];
                this.heavy[v] = u; // designate heavy child
            }
        }
    }

    _dfs2(v, h) {
        this.head[v] = h;         // chain head for v
        this.pos[v]  = this.cur++; // DFS position for segment tree
        if (this.heavy[v] !== -1) {
            this._dfs2(this.heavy[v], h); // extend chain to heavy child
        }
        for (const u of this.adj[v]) {
            if (u === this.parent[v] || u === this.heavy[v]) continue;
            this._dfs2(u, u); // light edge: start new chain from u
        }
    }

    // PATH QUERY: query segment tree on the path from u to v
    // (segment tree omitted for brevity)
    pathQuery(u, v) {
        let result = 0;
        while (this.head[u] !== this.head[v]) {
            // u and v are on different chains
            if (this.depth[this.head[u]] < this.depth[this.head[v]]) {
                [u, v] = [v, u]; // ensure u is on the deeper chain
            }
            // Query from head[u] to u on the segment tree
            result = Math.max(result, /* segTree.query(pos[head[u]], pos[u]) */ 0);
            u = this.parent[this.head[u]]; // jump to parent of chain head
        }
        // u and v are now on the same chain
        if (this.depth[u] > this.depth[v]) [u, v] = [v, u];
        result = Math.max(result, /* segTree.query(pos[u], pos[v]) */ 0);
        return result;
    }
}

