// AVL TREE ROTATIONS (conceptual implementation)

class AVLNode {
    constructor(val) {
        this.val = val;
        this.left = this.right = null;
        this.height = 1;
    }
}

function height(node) { return node ? node.height : 0; }
function balanceFactor(node) { return node ? height(node.left) - height(node.right) : 0; }
function updateHeight(node) {
    node.height = 1 + Math.max(height(node.left), height(node.right));
}

// LEFT ROTATION: when right subtree is too heavy
function leftRotate(z) {
    const y = z.right;
    const T2 = y.left;
    y.left = z;    // z becomes left child of y
    z.right = T2;  // T2 moves to z's right
    updateHeight(z);
    updateHeight(y);
    return y;      // y is the new root
}

// RIGHT ROTATION: when left subtree is too heavy
function rightRotate(z) {
    const y = z.left;
    const T3 = y.right;
    y.right = z;   // z becomes right child of y
    z.left = T3;   // T3 moves to z's left
    updateHeight(z);
    updateHeight(y);
    return y;      // y is the new root
}

// BALANCE: apply correct rotation based on balance factor
function balance(node) {
    updateHeight(node);
    const bf = balanceFactor(node);

    // LEFT HEAVY
    if (bf > 1) {
        if (balanceFactor(node.left) < 0) {
            node.left = leftRotate(node.left); // LEFT-RIGHT case
        }
        return rightRotate(node); // LEFT-LEFT case
    }
    // RIGHT HEAVY
    if (bf < -1) {
        if (balanceFactor(node.right) > 0) {
            node.right = rightRotate(node.right); // RIGHT-LEFT case
        }
        return leftRotate(node); // RIGHT-RIGHT case
    }
    return node; // already balanced
}

// RED-BLACK INVARIANTS (reference, not full implementation):
// 1. Every node is RED or BLACK
// 2. Root is BLACK
// 3. Every NULL leaf is BLACK
// 4. If a node is RED, both children are BLACK
// 5. All paths from any node to its descendant NULL leaves have equal BLACK count
// Height bound: <= 2 * log2(n+1)
// Used in: C++ std::map, Java TreeMap, Linux CFS scheduler

