// Alternatively solved with a max-heap + events
function getSkyline(buildings) {
    // Events: each building creates an enter event and exit event
    const events = [];
    for (const [l, r, h] of buildings) {
        events.push([l, -h]); // enter: negative height for sorting
        events.push([r,  h]); // exit: positive height
    }
    events.sort((a,b) => a[0] !== b[0] ? a[0]-b[0] : a[1]-b[1]);

    const result = [];
    const maxHeap = [0]; // heights of currently active buildings
    // Using sorted multiset (simulated with sorted array here)

    for (const [x, h] of events) {
        if (h < 0) maxHeap.push(-h); // enter: add height
        else {
            const idx = maxHeap.indexOf(h);
