function getSkyline(buildings){
  const events=[];
  for(const[l,r,h]of buildings){events.push([l,-h]);events.push([r,h]);}
  events.sort((a,b)=>a[0]!==b[0]?a[0]-b[0]:a[1]-b[1]);
  const result=[];const maxHeap=[0];
  for(const[x,h]of events){
    if(h<0)maxHeap.push(-h);
    else{const idx=maxHeap.indexOf(h);if(idx!==-1)maxHeap.splice(idx,1);}
    maxHeap.sort((a,b)=>b-a);const curMax=maxHeap[0];
    if(!result.length||result[result.length-1][1]!==curMax)result.push([x,curMax]);
  }
  return result;
}
